from marshmallow.experimental.context import Context

class TestContext:
    def test_context_creation(self):
        context = Context({"key": "value"})
        assert context.context == {"key": "value"}

    def test_context_enter_exit(self):
        with Context({"key": "value"}) as ctx:
            assert Context.get() == {"key": "value"}
        assert Context.get(None) is None

    def test_context_nested(self):
        with Context({"outer": "value"}) as outer_ctx:
            assert Context.get() == {"outer": "value"}
            with Context({"inner": "value"}) as inner_ctx:
                assert Context.get() == {"inner": "value"}
            assert Context.get() == {"outer": "value"}
        assert Context.get(None) is None

    def test_context_get_default(self):
        assert Context.get({"default": "value"}) == {"default": "value"}
        with Context({"key": "value"}) as ctx:
            assert Context.get({"default": "value"}) == {"key": "value"}

    def test_context_get_no_default(self):
        with pytest.raises(LookupError):
            Context.get()

    def test_context_reset_on_exception(self):
        class TestException(Exception):
            pass
        try:
            with Context({"key": "value"}) as ctx:
                raise TestException()
        except TestException:
